import base64
import shutil
import zlib
from pathlib import Path


base = Path(__file__).resolve().parent
main = base / "app" / "main.py"
if not main.exists():
    raise RuntimeError(
        "Coloca este archivo en la carpeta principal de HelioRegla"
    )

texto_actual = main.read_text(
    encoding="utf-8-sig"
).replace("\r\n", "\n")
if 'VERSION = "0.18.0"' not in texto_actual:
    raise RuntimeError(
        "Este actualizador necesita Ne-notoka "
        "HelioRegla 0.18.0"
    )

archivos = {'CHANGELOG.md': '', 'app/catalogo_regiones.py': '', 'app/dialogo_referencia.py': '', 'app/dialogos_regiones.py': '', 'app/i18n.py': '', 'app/main.py': '', 'app/referencia_solar.py': '', 'docs/ATAJOS.md': '', 'docs/GUIA_DE_USO.md': ''}
contenidos = {
    nombre: zlib.decompress(base64.b64decode(paquete))
    for nombre, paquete in archivos.items()
}

# Validar todo antes de modificar la instalación.
for nombre, contenido in contenidos.items():
    if nombre.endswith(".py"):
        compile(
            contenido.decode("utf-8-sig"),
            nombre,
            "exec",
        )

for nombre, contenido in contenidos.items():
    ruta = base / nombre
    ruta.parent.mkdir(parents=True, exist_ok=True)
    respaldo = ruta.with_name(ruta.name + ".bak_0180")
    if ruta.exists() and not respaldo.exists():
        shutil.copy2(ruta, respaldo)
    temporal = ruta.with_name(ruta.name + ".tmp_0190")
    temporal.write_bytes(contenido)
    temporal.replace(ruta)

print("Ne-notoka HelioRegla 0.19.0 instalado correctamente")
print("Se conservaron respaldos .bak_0180")
print("No requiere instalar paquetes adicionales")
print("Ejecuta: .\\.venv\\Scripts\\python.exe app\\main.py")
